    tokens: list of strings representing integers or operators '+', '-', '*', '/'.
    Returns the integer result. Division truncates toward zero.
    """
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/') and len(stack) >= 2:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
