def solve(n):
    """Return number of primes strictly less than n.
    Uses sieve of Eratosthenes.
    """
    if n <= 2:
        return 0
    sieve = bytearray(b'\x01') * n  # True means prime candidate
    sieve[0:2] = b'\x00\x00'  # 0 and 1 not prime
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:n:step] = b'\x00' * ((n - 1 - start)//step + 1)
    return sum(sieve)

