    """Return the determinant of an integer square matrix.
    The empty matrix (0x0) is defined to have determinant 1.
    Uses recursive Laplace expansion; suitable for small matrices.
    """
    def det(m):
        n = len(m)
        if n == 0:
            return 1
        if n == 1:
            return m[0][0]
        if n == 2:
            return m[0][0] * m[1][1] - m[0][1] * m[1][0]
        total = 0
        for col in range(n):
            # Build submatrix excluding first row and current column
            sub = [row[:col] + row[col+1:] for row in m[1:]]
            sign = -1 if col % 2 else 1
            total += sign * m[0][col] * det(sub)
        return total
    return det(mat)

