def compare():
    for _ in range(10000):
        # generate path with possible leading multiple slashes
        segs=[]
        leading_slashes='/'*random.randint(1,3)
        for i in range(random.randint(0,6)):
            choice=random.choice(['.', '..', '', ''.join(random.choices(string.ascii_letters, k=random.randint(1,3)))])
            segs.append(choice)
        path=leading_slashes + '/'.join(segs)
        # maybe trailing slash
        if random.choice([True, False]):
            path+='/'
        a=solve(path)
        b=posixpath.normpath(path)
        if not b.startswith('/'):
