def solve(path):
    """Simplify an absolute Unix file system path.
    Resolves '.' and '..' components, collapses multiple slashes, and removes any trailing slash.
    The root '/' is preserved.
    """
    # Split by '/', filter out empty and '.' components
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, we are at root; nothing to pop
        else:
            stack.append(part)
    # Join the remaining parts with '/' and ensure leading '/'
    simplified = '/' + '/'.join(stack)
    return simplified

