def solve(weights, values, capacity):
    """0/1 knapsack using dictionary DP to handle large capacities.
    Returns the maximum total value achievable without exceeding capacity.
    """
    if capacity <= 0 or not weights:
        return 0
    dp = {0: 0}  # weight -> max value
    for w, v in zip(weights, values):
        if w > capacity:
            # can't take item, skip
            continue
        # iterate over current states snapshot to avoid reuse within same item
        new_dp = dp.copy()
        for cur_w, cur_v in dp.items():
            new_w = cur_w + w
            if new_w <= capacity:
                new_v = cur_v + v
                if new_w not in new_dp or new_v > new_dp[new_w]:
                    new_dp[new_w] = new_v
        dp = new_dp
    # maximum value among all reachable weights
    return max(dp.values())

def solve(s: str) -> int:
    """Return length of longest substring without repeating characters.
    Uses sliding window with a dictionary of last seen positions.
    """
    last_index = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        if ch in last_index and last_index[ch] >= start:
            # character repeated inside current window, move start
            start = last_index[ch] + 1
        last_index[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Operators: +, -, *, /. Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # Avoid float precision issues by using integer arithmetic
                # Compute absolute division result then apply sign
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a < 0) ^ (b < 0) else 1
                result = abs(a) // abs(b)
                stack.append(sign * result)
        else:
            stack.append(int(token))
    return stack[0]

