def solve(n: int) -> int:
    """Return the number of prime numbers strictly less than *n*.
    Uses the Sieve of Eratosthenes with a bytearray for speed.
    """
    if n <= 2:
        return 0
    # sieve[i] == 1 means i is currently considered prime
    sieve = bytearray(b'\x01') * n
    sieve[0:2] = b'\x00\x00'  # 0 and 1 are not prime
    limit = int(n ** 0.5) + 1
    for p in range(2, limit):
        if sieve[p]:
            start = p * p
            if start >= n:
                continue
            sieve[start:n:p] = b'\x00' * ((n - start - 1) // p + 1)
    # sum of remaining 1s gives number of primes < n
    return sum(sieve)

